-- ============================================================
-- HOSTINGER MYSQL PRODUCTS TABLE DUMP (PART 1)
-- Target: MySQL / MariaDB (phpMyAdmin Compatible)
-- ============================================================

SET FOREIGN_KEY_CHECKS = 0;
SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO";
START TRANSACTION;
SET time_zone = "+00:00";

CREATE TABLE IF NOT EXISTS `products` (
  `id` VARCHAR(255) NOT NULL,
  `name` TEXT DEFAULT NULL,
  `cut` VARCHAR(100) DEFAULT NULL,
  `color` VARCHAR(100) DEFAULT NULL,
  `clarity` VARCHAR(100) DEFAULT NULL,
  `carat` DOUBLE DEFAULT 0,
  `certification` VARCHAR(100) DEFAULT NULL,
  `certId` VARCHAR(255) DEFAULT NULL,
  `price` DOUBLE DEFAULT 0,
  `stock` INT DEFAULT 1,
  `image` TEXT DEFAULT NULL,
  `description` TEXT DEFAULT NULL,
  `status` VARCHAR(100) DEFAULT 'In Stock',
  `data` LONGTEXT DEFAULT NULL,
  `updatedAt` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_certId` (`certId`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ON DUPLICATE KEY UPDATE name=VALUES(name), price=VALUES(price), stock=VALUES(stock), data=VALUES(data);

SET FOREIGN_KEY_CHECKS = 1;
COMMIT;
